powershell -NoProfile -Command "$map = @{}; $key = $null; foreach ($line in Get-Content 'protein_ids.txt') { $line = $line.Trim().TrimEnd('\').Trim(); if ($line -match '^ACCESSION\s+(\S+)') { $key = $Matches[1] -replace '\.\d+$', '' } elseif ($key -and $line) { $map[$key] = $line; $key = $null } }; Import-Csv 'input.csv' | ForEach-Object { $lookup = $_.paper_accession.Trim() -replace '\.\d+$', ''; if ($map.ContainsKey($lookup)) { $_.paper_accession = $map[$lookup] }; $_ } | Export-Csv 'output_csv.csv' -NoTypeInformation -Encoding UTF8"
